use vstd::prelude::*;

verus! {
    fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (result: (Vec<Vec<f32>>, Vec<Vec<f32>>))
        requires
            !x.is_empty() && !y.is_empty(),
        ensures
            let (grid_x, grid_y) = result;
            grid_x.len() == y.len() && grid_y.len() == y.len() &&
            forall |i: nat| 0 <= i < y.len() ==> grid_y[i].len() == x.len() &&
            forall |i: nat, j: nat| 0 <= i < y.len() && 0 <= j < x.len() ==> 
                grid_x[i][j] == x[j] && grid_y[i][j] == y[i],
    {
        let m = y.len();
        let n = x.len();
        
        let mut grid_x: Vec<Vec<f32>> = Vec::new();
        let mut grid_y: Vec<Vec<f32>> = Vec::new();

        // Initialize the output matrices
        for _ in 0..m {
            grid_x.push(Vec::new());
            grid_y.push(Vec::new());
        }

        // Fill the output matrices
        for i in 0..m
            invariant
                0 <= i <= m,
                forall |k: nat| 0 <= k < i ==> grid_y[k].len() == n,
                forall |k: nat| 0 <= k < i ==> grid_x[k].len() == n,
            decreases m - i,
        {
            for j in 0..n
                invariant
                    0 <= j <= n,
                    grid_y[i].len() == j,
                    grid_x[i].len() == j,
                decreases n - j,
            {
                grid_x[i].push(x[j]);
                grid_y[i].push(y[i]);
            }
        }

        (grid_x, grid_y)
    }
}

